/*
Rule 1: Set `tier` to 'premium' for any cardholder where `total_deposits >= 50000`.
Rule 2: Set `tier` to 'standard' for any cardholder where `total_deposits >= 10000` AND `total_deposits < 50000`.
Rule 3: Set `cashback_rate` to `swipes_this_month * 0.02` for cardholders where `tier = 'premium'`.
Rule 4: Set `high_risk_flag` to TRUE for any cardholder where `swipes_this_month >= 80` AND `total_deposits < 5000`

*/

DO $$
BEGIN

    UPDATE cardholders
    SET tier = 'premium'
    WHERE total_deposits >= 50000;

    UPDATE cardholders
    SET tier = 'standard'
    WHERE total_deposits >= 10000 AND total_deposits < 50000;

    UPDATE cardholders
    SET cashback_rate = swipes_this_month * 0.02
    WHERE tier  = 'premium';

    UPDATE cardholders
    SET high_risk_flag = true
    WHERE swipes_this_month >= 80 AND total_deposits < 5000;

END $$;


SELECT * FROM cardholders ORDER BY cardholder_id;
